set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',false);
select previsio_request_leave('A','22222222-2222-2222-2222-222222222222',current_date+30,current_date+32,'holiday','Test request');
select test_assert((select status='pending' from leave_requests where id='22222222-2222-2222-2222-222222222222'),'request starts pending');
select test_assert((select count(*)=0 from work_shifts where kind='leave'),'request does not grant leave');
select test_assert(test_denied($q$select previsio_review_leave('22222222-2222-2222-2222-222222222222','approved')$q$),'staff cannot approve');
select test_assert(test_denied($q$update leave_requests set status='approved'$q$),'direct approval blocked');
select test_assert(test_denied($q$insert into work_shifts(id,business_id,user_id,date,kind) values('BYPASS','A',3,current_date+30,'leave')$q$),'direct leave insertion blocked');
select test_assert(test_denied($q$select previsio_request_leave('B',gen_random_uuid(),current_date+30,current_date+32,'holiday','')$q$),'cross business request blocked');
select test_assert(test_denied($q$select previsio_request_leave('A',gen_random_uuid(),current_date+31,current_date+33,'holiday','')$q$),'overlapping requests blocked');
select previsio_request_leave('A','22222222-2222-2222-2222-222222222222',current_date+30,current_date+32,'holiday','Test request');
select test_assert((select count(*)=1 from leave_requests),'identical request retry deduplicates');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select test_assert((select count(*)=0 from leave_requests),'other business cannot read requests');
select test_assert(test_denied($q$select previsio_review_leave('22222222-2222-2222-2222-222222222222','approved')$q$),'other business cannot approve');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',false);
select previsio_review_leave('22222222-2222-2222-2222-222222222222','approved');
select previsio_review_leave('22222222-2222-2222-2222-222222222222','approved');
select test_assert((select count(*)=3 from work_shifts where kind='leave'),'range approval creates each day exactly once');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',false);
delete from work_shifts where kind='leave';
select test_assert((select count(*)=3 from work_shifts where kind='leave'),'staff cannot delete approved leave');
update work_shifts set kind='worked' where kind='leave';
select test_assert((select count(*)=3 from work_shifts where kind='leave'),'staff cannot rewrite approved leave');
select test_assert(test_denied($q$insert into work_shifts(id,business_id,user_id,date,kind) values('OVERLAP','A',3,current_date+30,'worked')$q$),'work cannot overlap approved leave');
select previsio_request_leave('A','33333333-3333-3333-3333-333333333333',current_date+40,current_date+41,'personal','');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select previsio_review_leave('33333333-3333-3333-3333-333333333333','rejected');
select test_assert((select count(*)=3 from work_shifts where kind='leave'),'rejection creates no leave');
reset role;

-- A pending request also blocks scheduling, even before approval creates leave rows.
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',false);
select previsio_request_leave('A','33333333-2222-2222-2222-222222222222',current_date+60,current_date+62,'holiday','Scheduling guard');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',false);
select test_assert(test_denied($q$insert into rota_shifts(id,business_id,"userId",date) values('PENDING-OVERLAP','A',3,current_date+60)$q$),'pending leave prevents rota insert');
select test_assert(test_denied($q$insert into rota_shifts(id,business_id,"userId",date) values('PENDING-END','A',3,current_date+62)$q$),'last leave day is inclusive');
insert into rota_shifts(id,business_id,"userId",date) values('OUTSIDE-LEAVE','A',3,current_date+63);
select test_assert(test_denied($q$update rota_shifts set date=current_date+61 where id='OUTSIDE-LEAVE'$q$),'moving rota into leave rejected');
select previsio_review_leave('33333333-2222-2222-2222-222222222222','rejected');
insert into rota_shifts(id,business_id,"userId",date) values('REJECTED-LEAVE','A',3,current_date+60);
reset role;
